{"code": "from collections import deque

def solve():
    capacities = (16, 21, 16, 21, 16)
    target = 14
    # State: (a, b, c, d, e)
    initial_state = (0, 0, 0, 0, 0)
    queue = deque([(initial_state, [])])
    visited = {initial_state}

    while queue:
        current_state, path = queue.popleft()

        if any(v == target for v in current_state):
            return path

        # Fill
        for i in range(5):
            if current_state[i] < capacities[i]:
                new_list = list(current_state)
                new_list[i] = capacities[i]
                new_state = tuple(new_list)
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, path + [f'fill {chr(65+i)}']))

        # Empty
        for i in range(5):
            if current_state[i] > 0:
                new_list = list(current_state)
                new_list[i] = 0
                new_state = tuple(new_list)
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, path + [f'empty {chr(65+i)}']))

        # Pour
        for i in range(5):
            for j in range(5):
                if i != j and current_state[i] > 0 and current_state[j] < capacities[j]:
                    pour_amount = min(current_state[i], capacities[j] - current_state[j])
                    new_list = list(current_state)
                    new_list[i] -= pour_amount
                    new_list[j] += pour_amount
                    new_state = tuple(new_list)
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, path + [f'pour {chr(65+i)}->{chr(65+j)}']))
    return None

print(solve())"}

